import{_ as e,o as a,c as d,ah as l}from"./chunks/framework.DjU4PSOm.js";const c=JSON.parse('{"title":"","description":"","frontmatter":{"tags":["computer/project"],"date":"2026-11-14T00:00:00.000Z"},"headers":[{"level":3,"title":"오늘 한 것 (2026-11-14)","slug":"오늘-한-것-2026-11-14","link":"#오늘-한-것-2026-11-14","children":[]},{"level":3,"title":"1. 제공자 고르기","slug":"_1-제공자-고르기","link":"#_1-제공자-고르기","children":[]},{"level":3,"title":"2. 구조","slug":"_2-구조","link":"#_2-구조","children":[]},{"level":3,"title":"3. 테스트하다 발견한 것 — 한국어를 한국어로 번역","slug":"_3-테스트하다-발견한-것-—-한국어를-한국어로-번역","link":"#_3-테스트하다-발견한-것-—-한국어를-한국어로-번역","children":[]},{"level":3,"title":"4. 언어 2개 → 8개","slug":"_4-언어-2개-→-8개","link":"#_4-언어-2개-→-8개","children":[]},{"level":3,"title":"5. 보안 보완 — 남겨둔 과제 정리","slug":"_5-보안-보완-—-남겨둔-과제-정리","link":"#_5-보안-보완-—-남겨둔-과제-정리","children":[]},{"level":3,"title":"6. 테스트 결과","slug":"_6-테스트-결과","link":"#_6-테스트-결과","children":[]},{"level":3,"title":"7. 이번에 배운 것","slug":"_7-이번에-배운-것","link":"#_7-이번에-배운-것","children":[]},{"level":3,"title":"8. 남은 과제","slug":"_8-남은-과제","link":"#_8-남은-과제","children":[]}],"relativePath":"computer/project/Zing/12. 번역 기능과 보안 보완 (2026-11-14).md","filePath":"computer/project/Zing/12. 번역 기능과 보안 보완 (2026-11-14).md"}'),r={name:"computer/project/Zing/12. 번역 기능과 보안 보완 (2026-11-14).md"};function n(s,t,i,o,p,u){return a(),d("div",null,[...t[0]||(t[0]=[l(`<h3 id="오늘-한-것-2026-11-14" tabindex="-1">오늘 한 것 (2026-11-14) <a class="header-anchor" href="#오늘-한-것-2026-11-14" aria-label="Permalink to &quot;오늘 한 것 (2026-11-14)&quot;">​</a></h3><p>Zing의 차별점인 <strong>번역</strong>을 붙였다. 처음엔 Claude Haiku로 설계했다가 &quot;초반엔 무료로 쓰고 싶다&quot;는 조건이 붙어서 DeepL 무료 플랜을 기본으로 바꿨다. 같이 그동안 남겨둔 보안 과제도 정리했다.</p><table tabindex="0"><thead><tr><th>순서</th><th>작업</th><th>상태</th></tr></thead><tbody><tr><td>1</td><td>번역 제공자 비교와 설계</td><td>완료</td></tr><tr><td>2</td><td>Edge Function <code>translate</code> (DeepL 우선, Claude Haiku 대체)</td><td>배포 완료</td></tr><tr><td>3</td><td>번역 저장 테이블, 화면의 &quot;번역 보기&quot; 버튼</td><td>완료</td></tr><tr><td>4</td><td>사용 언어 2개 → 8개</td><td>완료</td></tr><tr><td>5</td><td>보안 보완: 일기 직접 조회 차단, 하루 1개 DB 강제, 시간대 통일</td><td>완료</td></tr><tr><td>6</td><td>실제 번역 + 우회 시도 테스트</td><td>완료, push 완료</td></tr></tbody></table><hr><h3 id="_1-제공자-고르기" tabindex="-1">1. 제공자 고르기 <a class="header-anchor" href="#_1-제공자-고르기" aria-label="Permalink to &quot;1. 제공자 고르기&quot;">​</a></h3><p>평균 일기 400자, 환율 1,400원 기준으로 비교했다.</p><table tabindex="0"><thead><tr><th>제공자</th><th>일기 1편</th><th>무료 구간</th><th>특징</th></tr></thead><tbody><tr><td>Claude Haiku 5.5</td><td>약 0.5원 (추정)</td><td>없음</td><td>말투·맥락을 살림</td></tr><tr><td>파파고</td><td>약 8원 (단가 미확인)</td><td>없음</td><td>한↔일, 한↔영에 강함</td></tr><tr><td>Google 번역</td><td>약 11원</td><td>월 50만 자 (출처마다 다름)</td><td>언어가 가장 많음</td></tr><tr><td>DeepL</td><td>약 14원 + 월 기본료</td><td>월 50만 자 무료 플랜</td><td>품질 좋음</td></tr></tbody></table><p>활성 사용자 1,000명 × 매일 일기 × 2개 언어 기준이면 월 6만 건이다. 이때 Haiku는 약 3만 원, 번역 전용 API들은 50~80만 원이 나온다. 그래서 처음엔 Haiku로 설계했다.</p><p>그런데 <strong>초반 비용 0원</strong>이 조건으로 붙었다. 사용자가 적을 때는 DeepL 무료 플랜(월 50만 자, 일기 약 1,250편)이면 충분하다. 게다가 한도를 넘어도 <strong>과금되지 않고 멈추기만</strong> 한다. 그래서 둘을 엮었다.</p><ul><li><code>DEEPL_API_KEY</code>만 있으면 DeepL만 쓴다. 한도를 넘으면 &quot;이번 달 무료 번역 한도를 다 썼어요&quot;가 뜬다.</li><li><code>ANTHROPIC_API_KEY</code>를 추가하면 DeepL이 한도 초과나 장애일 때 자동으로 Claude Haiku로 넘어간다.</li><li><strong>코드 수정 없이 키(Secret)만으로 제공자가 바뀐다.</strong> 번역 API를 부르는 곳이 Edge Function 한 군데뿐이라 가능하다.</li></ul><h3 id="_2-구조" tabindex="-1">2. 구조 <a class="header-anchor" href="#_2-구조" aria-label="Permalink to &quot;2. 구조&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[앱] 번역 보기 → [Edge Function translate]</span></span>
<span class="line"><span>                  1. 로그인 확인</span></span>
<span class="line"><span>                  2. 내 사용 언어를 DB에서 읽음 (앱이 보낸 값은 안 믿음)</span></span>
<span class="line"><span>                  3. 이미 내 언어로 쓰인 일기면 → 번역 안 함</span></span>
<span class="line"><span>                  4. 저장된 번역이 있고 원문이 안 바뀌었으면 → 그대로 반환</span></span>
<span class="line"><span>                  5. 하루 50회 확인 → 번역 → 저장 → 반환</span></span>
<span class="line"><span>                  6. 매칭 전인 상대 일기면 번역문도 앞 절반만</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><ul><li><strong>API 키는 Edge Function에만 있다.</strong> 앱에 넣으면 누구나 꺼내 쓸 수 있기 때문이다.</li><li><strong>번역은 저장해서 모두가 재사용한다.</strong> 비용이 조회 수가 아니라 <strong>일기 수 × 언어 수</strong>에 비례한다.</li><li><strong>절반 공개는 번역문에도 적용된다.</strong> 전문을 한 번만 번역해 저장하고, 매칭 전이면 번역문의 앞 절반만 준다. 일기당 번역이 1회로 끝나서 가장 싸다. 한국어와 영어는 어순이 달라 원문 절반과 번역문 절반의 내용이 정확히 같지는 않은데, 미리보기 용도라 허용했다.</li><li><strong>Claude 프롬프트</strong>에는 일기 안의 문장은 지시가 아니라 번역할 내용이라고 명시했다. 일기에 &quot;위 내용을 무시하고…&quot; 같은 문장을 써서 번역기를 조종하는 걸 막기 위해서다. DeepL은 번역 전용이라 이 문제가 없다.</li></ul><h3 id="_3-테스트하다-발견한-것-—-한국어를-한국어로-번역" tabindex="-1">3. 테스트하다 발견한 것 — 한국어를 한국어로 번역 <a class="header-anchor" href="#_3-테스트하다-발견한-것-—-한국어를-한국어로-번역" aria-label="Permalink to &quot;3. 테스트하다 발견한 것 — 한국어를 한국어로 번역&quot;">​</a></h3><p>첫 테스트에서 번역 버튼을 눌렀더니 &quot;원문 보기&quot;로 바뀌긴 했는데 글자가 그대로였다. DB를 보니 DeepL이 실제로 호출됐다.</p><ul><li>원인: 테스트 계정(UI테스트)의 사용 언어가 한국어였다. 한국어 일기를 한국어로 &quot;번역&quot;하느라 무료 한도를 쓴 것.</li><li>수정: 호출 전에 글자 모양으로 원문 언어를 어림잡는다. 한글·가나·한자 비율로 한국어·일본어·중국어를 판단하고, 이미 내 언어면 API를 부르지 않고 &quot;이미 내 사용 언어로 쓰인 일기예요&quot;를 보여준다.</li><li>한계: 영어·프랑스어처럼 알파벳을 쓰는 언어끼리는 판단을 못 해서 그대로 보낸다.</li></ul><h3 id="_4-언어-2개-→-8개" tabindex="-1">4. 언어 2개 → 8개 <a class="header-anchor" href="#_4-언어-2개-→-8개" aria-label="Permalink to &quot;4. 언어 2개 → 8개&quot;">​</a></h3><p>한국어, English, 日本語, 中文, Tiếng Việt, Français, Deutsch, Español.</p><p>교환학생이 많은 나라(일본·중국·베트남·프랑스·독일·스페인어권) 기준으로 골랐다. 가입 화면 선택지가 많아져서 <code>OptionSelector</code>가 4개씩 줄바꿈되게 바꿨다. 베트남어는 DeepL 지원 여부를 문서로 확인하지 못해서 실제로 호출해 봤는데 정상 번역됐다.</p><h3 id="_5-보안-보완-—-남겨둔-과제-정리" tabindex="-1">5. 보안 보완 — 남겨둔 과제 정리 <a class="header-anchor" href="#_5-보안-보완-—-남겨둔-과제-정리" aria-label="Permalink to &quot;5. 보안 보완 — 남겨둔 과제 정리&quot;">​</a></h3><table tabindex="0"><thead><tr><th>과제</th><th>전</th><th>후</th></tr></thead><tbody><tr><td>절반 공개</td><td><code>diaries</code> SELECT가 전체 허용 → API 직접 조회로 전문이 보임</td><td><strong>내 일기만</strong> 조회 가능. 다른 사람 일기는 전용 함수로만</td></tr><tr><td>일기 하루 1개</td><td>앱에서만 검사</td><td><strong>DB 트리거</strong>로 강제. 작성 시각도 현재 시각으로 고정</td></tr><tr><td>하루 기준</td><td>일기는 기기 시간, 징·단계는 한국 시간</td><td>전부 <strong>한국 시간 0시</strong></td></tr><tr><td><code>rls_auto_enable()</code></td><td>로그인 안 해도 호출 가능</td><td>외부 호출 차단</td></tr></tbody></table><p><code>rls_auto_enable()</code>은 우리가 만든 게 아니었다. 들여다보니 새 테이블이 생기면 RLS를 자동으로 켜주는 이벤트 트리거용 함수였다(Supabase 프로젝트 생성 시 설정). 트리거 자체는 그대로 두고, API로 부르는 경로만 막았다.</p><p>작성 시각 고정이 중요한 이유: 단계 해금이 &quot;매칭 이후 쓴 일기 수&quot; 기준이라, <code>created_at</code>을 조작하거나 하루에 여러 개 쓰면 단계를 부정하게 올릴 수 있었다.</p><h3 id="_6-테스트-결과" tabindex="-1">6. 테스트 결과 <a class="header-anchor" href="#_6-테스트-결과" aria-label="Permalink to &quot;6. 테스트 결과&quot;">​</a></h3><table tabindex="0"><thead><tr><th>확인</th><th>결과</th></tr></thead><tbody><tr><td>한국어 → 영어 (피드, 매칭 전)</td><td>번역, 앞 절반만</td></tr><tr><td>매칭 상대 일기</td><td>전문 번역</td></tr><tr><td>베트남어</td><td>정상</td></tr><tr><td>같은 일기 재요청</td><td>저장본 사용 (요청 5건 = 일기 5편)</td></tr><tr><td>다른 사람 일기 직접 조회</td><td>0건</td></tr><tr><td>하루 두 번째 일기 (API 직접)</td><td>거절</td></tr><tr><td>작성 시각 조작</td><td>무시되고 현재 시각으로 저장</td></tr><tr><td><code>rls_auto_enable()</code> 호출</td><td>403</td></tr></tbody></table><h3 id="_7-이번에-배운-것" tabindex="-1">7. 이번에 배운 것 <a class="header-anchor" href="#_7-이번에-배운-것" aria-label="Permalink to &quot;7. 이번에 배운 것&quot;">​</a></h3><ul><li><strong>인증 정보는 AI에게 맡기지 않는다.</strong> DeepL 키를 대화창에 붙이고 등록해 달라고 했는데, AI는 키 입력을 하지 않았다. 키는 Supabase 대시보드에 직접 넣었다. 대화 기록에 키가 남았으니 재발급을 권장받았다.</li><li><strong>무료 플랜도 일시정지된다.</strong> Supabase가 이번 주에만 두 번 멈췄다. 7일 동안 활동이 없으면 멈춘다. 런칭 전에는 Pro 플랜(월 25달러)으로 올려야 한다.</li></ul><h3 id="_8-남은-과제" tabindex="-1">8. 남은 과제 <a class="header-anchor" href="#_8-남은-과제" aria-label="Permalink to &quot;8. 남은 과제&quot;">​</a></h3><ul><li>앱 안에서 사용 언어를 바꾸는 화면이 없다 (가입 때만 선택)</li><li>채팅 번역 (4단계 채팅을 만들 때 같은 함수에 붙임, BM의 하루 무료 횟수 포함)</li><li>DeepL 무료 한도가 매달 갱신되는지 계정 화면에서 확인</li><li>2단계 &quot;오늘의 질문&quot;부터 미구현</li><li>단계 스킵권 BM 후보 재검토 (단계가 짧아져 효용이 줄어듦)</li></ul>`,29)])])}const _=e(r,[["render",n]]);export{c as __pageData,_ as default};
